16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: a leading '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    @Email
63	    private String email;
64	
65	    @Column(name = "registration_date", columnDefinition = "DATE")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date", columnDefinition = "DATE")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "household_size")
81	    private Integer householdSize;
82	
83	    @Column(name = "postcode")
84	    private String postcode;
85	
86	    @Column(name = "possible_duplicate")
87	    private Boolean possibleDuplicate;
88	
89	    @Column(name = "possible_duplicate_of")
90	    private Integer possibleDuplicateOf;
91	
92	    @Column(name = "deleted", nullable = false)
93	    private boolean deleted = false;
94	
95	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
96	    private Set<Pet> pets;
97	
98	    public String getTitle() {
99	        return this.title;
100	    }
101	
102	    public void setTitle(String title) {
103	        this.title = title;
104	    }
105	
106	    /**
107	     * The owner's salutation, derived from the {@link #title} and last name: {@code title + ' ' +
108	     * lastName} when a title is present, or just the last name when no title was supplied.
109	     */
110	    @Transient
111	    public String getSalutation() {
112	        if (this.title == null || this.title.isBlank()) {
113	            return getLastName();
114	        }
115	        return this.title + " " + getLastName();
116	    }
117	
118	    public String getAddress() {
119	        return this.address;
120	    }
121	
122	    public void setAddress(String address) {
123	        this.address = address;
124	    }
125	
126	    public String getAddressLine1() {
127	        return this.addressLine1;
128	    }
129	
130	    public void setAddressLine1(String addressLine1) {
131	        this.addressLine1 = addressLine1;
132	    }
133	
134	    public String getAddressLine2() {
135	        return this.addressLine2;
136	    }
137	
138	    public void setAddressLine2(String addressLine2) {
139	        this.addressLine2 = addressLine2;
140	    }
141	
142	    public String getCity() {
143	        return this.city;
144	    }
145	
146	    public void setCity(String city) {
147	        this.city = city;
148	    }
149	
150	    public String getTelephone() {
151	        return this.telephone;
152	    }
153	
154	    public void setTelephone(String telephone) {
155	        this.telephone = telephone;
156	    }
157	
158	    public String getEmail() {
159	        return this.email;
160	    }
161	
162	    /**
163	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
164	     * {@code null} value (email omitted) is preserved as {@code null}.
165	     */
166	    public void setEmail(String email) {
167	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
168	    }
169	
170	    public LocalDate getRegistrationDate() {
171	        return this.registrationDate;
172	    }
173	
174	    public void setRegistrationDate(LocalDate registrationDate) {
175	        this.registrationDate = registrationDate;
176	    }
177	
178	    public LocalDate getBirthDate() {
179	        return this.birthDate;
180	    }
181	
182	    public void setBirthDate(LocalDate birthDate) {
183	        this.birthDate = birthDate;
184	    }
185	
186	    /**
187	     * The owner's age band, derived from {@link #birthDate} measured against the
188	     * {@link #registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64
189	     * inclusive, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
190	     * supplied, so the field is simply absent from the response.
191	     */
192	    @Transient
193	    public String getAgeBand() {
194	        if (this.birthDate == null) {
195	            return null;
196	        }
197	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
198	        int age = java.time.Period.between(this.birthDate, reference).getYears();
199	        if (age < 18) {
200	            return "MINOR";
201	        }
202	        if (age < 65) {
203	            return "ADULT";
204	        }
205	        return "SENIOR";
206	    }
207	
208	    /** National-number length by country code, mirroring the create-time E.164 normalization. */
209	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
210	
211	    /**
212	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
213	     * national digits grouped in threes from the left (e.g. {@code +61412345678 -> +61 412 345 678}).
214	     * The country code is recognised from the known set ({@code +61} with 9 national digits, {@code +1}
215	     * with 10) that the create-time normalization produces. Values that are absent or not in E.164 form
216	     * are returned unchanged, so the raw {@link #telephone} still stands in for a display value.
217	     */
218	    @Transient
219	    public String getTelephoneDisplay() {
220	        if (this.telephone == null || !this.telephone.startsWith("+")) {
221	            return this.telephone;
222	        }
223	        String digits = this.telephone.substring(1);
224	        if (!digits.matches("[0-9]+")) {
225	            return this.telephone;
226	        }
227	        String countryCode = null;
228	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
229	            if (digits.startsWith(entry.getKey())
230	                && digits.length() - entry.getKey().length() == entry.getValue()) {
231	                countryCode = entry.getKey();
232	                break;
233	            }
234	        }
235	        if (countryCode == null) {
236	            return this.telephone;
237	        }
238	        String national = digits.substring(countryCode.length());
239	        StringBuilder grouped = new StringBuilder();
240	        for (int i = 0; i < national.length(); i += 3) {
241	            if (grouped.length() > 0) {
242	                grouped.append(' ');
243	            }
244	            grouped.append(national, i, Math.min(i + 3, national.length()));
245	        }
246	        return "+" + countryCode + " " + grouped;
247	    }
248	
249	    public String getCustomerCode() {
250	        return this.customerCode;
251	    }
252	
253	    public void setCustomerCode(String customerCode) {
254	        this.customerCode = customerCode;
255	    }
256	
257	    /**
258	     * A single Luhn check digit (0-9) computed over the digits contained in the
259	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
260	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
261	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
262	     * is assigned.
263	     */
264	    @Transient
265	    public Integer getCheckDigit() {
266	        if (this.customerCode == null) {
267	            return null;
268	        }
269	        int sum = 0;
270	        boolean dbl = true;
271	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
272	            char c = this.customerCode.charAt(i);
273	            if (c < '0' || c > '9') {
274	                continue;
275	            }
276	            int d = c - '0';
277	            if (dbl) {
278	                d *= 2;
279	                if (d > 9) {
280	                    d -= 9;
281	                }
282	            }
283	            sum += d;
284	            dbl = !dbl;
285	        }
286	        return (10 - (sum % 10)) % 10;
287	    }
